import React, { useState, useEffect } from 'react';
import {
  Container,
  Typography,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Button,
  Box,
  Chip,
  Alert,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  CircularProgress,
} from '@mui/material';
import { applicationsAPI } from '../services/api';
import { useAuth } from '../context/AuthContext';

const Institutions = () => {
  const { currentUser } = useAuth();
  const [institutions, setInstitutions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [applyingCourseId, setApplyingCourseId] = useState(null);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [selectedInstitution, setSelectedInstitution] = useState(null);
  const [dialogOpen, setDialogOpen] = useState(false);

  // Fetch real institutions from backend
  useEffect(() => {
    fetchInstitutions();
  }, []);

  const fetchInstitutions = async () => {
    try {
      setLoading(true);
      // For now, we'll use mock data. In real app, you'd fetch from /api/institutions
      const mockInstitutions = [
        {
          id: 'inst1',
          name: 'National University of Lesotho',
          email: 'info@nul.ls',
          phone: '+266 2234 0000',
          address: 'Roma, Lesotho',
          description: 'The premier institution of higher learning in Lesotho offering diverse programs across multiple faculties.',
          status: 'active',
          faculties: [
            {
              id: 'f1',
              name: 'Faculty of Science & Technology',
              courses: [
                { id: 'c1', name: 'Computer Science', duration: '4 years', fees: 15000, seats: 50 },
                { id: 'c2', name: 'Electrical Engineering', duration: '4 years', fees: 18000, seats: 40 },
                { id: 'c3', name: 'Civil Engineering', duration: '4 years', fees: 17000, seats: 45 }
              ]
            },
            {
              id: 'f2',
              name: 'Faculty of Humanities',
              courses: [
                { id: 'c4', name: 'Business Administration', duration: '3 years', fees: 12000, seats: 60 },
                { id: 'c5', name: 'Education', duration: '4 years', fees: 10000, seats: 80 },
                { id: 'c6', name: 'Law', duration: '4 years', fees: 16000, seats: 35 }
              ]
            }
          ]
        },
        {
          id: 'inst2',
          name: 'Limkokwing University of Creative Technology',
          email: 'admissions@limkokwing.ls',
          phone: '+266 2231 2222',
          address: 'Maseru, Lesotho',
          description: 'Creative innovation university focusing on technology, design, and creative industries.',
          status: 'active',
          faculties: [
            {
              id: 'f3',
              name: 'Faculty of Creative Technology',
              courses: [
                { id: 'c7', name: 'Graphic Design', duration: '3 years', fees: 16000, seats: 30 },
                { id: 'c8', name: 'Software Engineering', duration: '4 years', fees: 17000, seats: 35 },
                { id: 'c9', name: 'Multimedia Design', duration: '3 years', fees: 15500, seats: 25 }
              ]
            },
            {
              id: 'f4',
              name: 'Faculty of Business & Communication',
              courses: [
                { id: 'c10', name: 'Business Management', duration: '3 years', fees: 14000, seats: 40 },
                { id: 'c11', name: 'Public Relations', duration: '3 years', fees: 13500, seats: 30 }
              ]
            }
          ]
        },
        {
          id: 'inst3',
          name: 'Lesotho College of Education',
          email: 'info@lce.ac.ls',
          phone: '+266 2232 1111',
          address: 'Maseru, Lesotho',
          description: 'Dedicated to training quality teachers and education professionals for Lesotho.',
          status: 'active',
          faculties: [
            {
              id: 'f5',
              name: 'Faculty of Education',
              courses: [
                { id: 'c12', name: 'Primary Education', duration: '3 years', fees: 9000, seats: 100 },
                { id: 'c13', name: 'Secondary Education', duration: '4 years', fees: 11000, seats: 75 },
                { id: 'c14', name: 'Special Needs Education', duration: '3 years', fees: 9500, seats: 40 }
              ]
            }
          ]
        }
      ];
      setInstitutions(mockInstitutions);
    } catch (err) {
      setError('Failed to load institutions');
    } finally {
      setLoading(false);
    }
  };

  const applyForCourse = async (institutionId, courseId) => {
    try {
      setApplyingCourseId(courseId);
      setError('');
      setSuccess('');
      
      await applicationsAPI.applyForCourse({
        institutionId,
        courseId,
        documents: []
      });
      
      setSuccess('Successfully applied for the course!');
      setDialogOpen(false);
    } catch (err) {
      console.error('Apply error:', err);
      setError(err.response?.data?.error || 'Failed to apply for course. Please try again.');
    } finally {
      setApplyingCourseId(null);
    }
  };

  const openInstitutionDetails = (institution) => {
    setSelectedInstitution(institution);
    setDialogOpen(true);
  };

  const closeDialog = () => {
    setDialogOpen(false);
    setSelectedInstitution(null);
  };

  const getTotalCourses = (institution) => {
    return institution.faculties.reduce((total, faculty) => total + faculty.courses.length, 0);
  };

  if (loading) {
    return (
      <Container maxWidth="lg" sx={{ mt: 4, mb: 4, display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: '50vh' }}>
        <Box textAlign="center">
          <CircularProgress size={60} />
          <Typography variant="h6" sx={{ mt: 2 }}>Loading institutions...</Typography>
        </Box>
      </Container>
    );
  }

  return (
    <Container maxWidth="lg" sx={{ mt: 4, mb: 4 }}>
      <Typography variant="h4" gutterBottom>
        Higher Learning Institutions
      </Typography>
      <Typography variant="body1" color="textSecondary" sx={{ mb: 3 }}>
        Discover and apply to courses at institutions across Lesotho
      </Typography>

      {error && (
        <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError('')}>
          {error}
        </Alert>
      )}

      {success && (
        <Alert severity="success" sx={{ mb: 2 }} onClose={() => setSuccess('')}>
          {success}
        </Alert>
      )}

      <TableContainer component={Paper} elevation={3}>
        <Table sx={{ minWidth: 650 }} aria-label="institutions table">
          <TableHead sx={{ backgroundColor: 'primary.main' }}>
            <TableRow>
              <TableCell sx={{ color: 'white', fontWeight: 'bold' }}>Institution Name</TableCell>
              <TableCell sx={{ color: 'white', fontWeight: 'bold' }}>Location</TableCell>
              <TableCell sx={{ color: 'white', fontWeight: 'bold' }}>Contact</TableCell>
              <TableCell sx={{ color: 'white', fontWeight: 'bold' }}>Available Courses</TableCell>
              <TableCell sx={{ color: 'white', fontWeight: 'bold' }}>Status</TableCell>
              <TableCell sx={{ color: 'white', fontWeight: 'bold' }}>Actions</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {institutions.map((institution) => (
              <TableRow 
                key={institution.id}
                sx={{ 
                  '&:last-child td, &:last-child th': { border: 0 },
                  '&:hover': { backgroundColor: 'action.hover' }
                }}
              >
                <TableCell component="th" scope="row" sx={{ fontWeight: 'bold' }}>
                  {institution.name}
                </TableCell>
                <TableCell>{institution.address}</TableCell>
                <TableCell>
                  <Box>
                    <Typography variant="body2">{institution.email}</Typography>
                    <Typography variant="body2">{institution.phone}</Typography>
                  </Box>
                </TableCell>
                <TableCell>
                  <Chip 
                    label={`${getTotalCourses(institution)} courses`} 
                    color="info"
                    variant="outlined"
                  />
                </TableCell>
                <TableCell>
                  <Chip 
                    label={institution.status} 
                    color={institution.status === 'active' ? 'success' : 'default'}
                    size="small"
                  />
                </TableCell>
                <TableCell>
                  <Button
                    variant="contained"
                    onClick={() => openInstitutionDetails(institution)}
                  >
                    View Courses
                  </Button>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </TableContainer>

      {/* Institution Details Dialog */}
      <Dialog open={dialogOpen} onClose={closeDialog} maxWidth="lg" fullWidth>
        <DialogTitle>
          {selectedInstitution?.name} - Available Courses
        </DialogTitle>
        <DialogContent>
          {selectedInstitution && (
            <Box>
              <Typography variant="body1" paragraph>
                {selectedInstitution.description}
              </Typography>
              
              {selectedInstitution.faculties.map((faculty) => (
                <Box key={faculty.id} sx={{ mb: 4 }}>
                  <Typography variant="h6" gutterBottom color="primary" sx={{ borderBottom: '2px solid', borderColor: 'primary.main', pb: 1 }}>
                    {faculty.name}
                  </Typography>
                  <TableContainer component={Paper} variant="outlined" sx={{ mt: 2 }}>
                    <Table size="small">
                      <TableHead>
                        <TableRow>
                          <TableCell sx={{ fontWeight: 'bold' }}>Course Name</TableCell>
                          <TableCell sx={{ fontWeight: 'bold' }}>Duration</TableCell>
                          <TableCell sx={{ fontWeight: 'bold' }}>Fees (M)</TableCell>
                          <TableCell sx={{ fontWeight: 'bold' }}>Seats</TableCell>
                          <TableCell sx={{ fontWeight: 'bold' }}>Action</TableCell>
                        </TableRow>
                      </TableHead>
                      <TableBody>
                        {faculty.courses.map((course) => (
                          <TableRow key={course.id}>
                            <TableCell sx={{ fontWeight: 'medium' }}>{course.name}</TableCell>
                            <TableCell>{course.duration}</TableCell>
                            <TableCell>{course.fees}</TableCell>
                            <TableCell>
                              <Chip 
                                label={course.seats} 
                                color={course.seats > 20 ? 'success' : 'warning'}
                                size="small"
                              />
                            </TableCell>
                            <TableCell>
                              <Button
                                variant="outlined"
                                size="small"
                                onClick={() => applyForCourse(selectedInstitution.id, course.id)}
                                disabled={applyingCourseId === course.id}
                              >
                                {applyingCourseId === course.id ? 'Applying...' : 'Apply'}
                              </Button>
                            </TableCell>
                          </TableRow>
                        ))}
                      </TableBody>
                    </Table>
                  </TableContainer>
                </Box>
              ))}
            </Box>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={closeDialog}>Close</Button>
        </DialogActions>
      </Dialog>
    </Container>
  );
};

export default Institutions;
